alter table sourceenergy_one.authorization_requests add column if not exists expires_at timestamptz; alter table sourceenergy_one.authorization_requests add column if not exists consumed_at timestamptz; create unique index if not exists execution_receipts_executed_correlation_adapter_uidx on sourceenergy_one.execution_receipts(correlation_id, adapter_key) where status='executed'; create or replace function sourceenergy_one.execute_authorized_action(p_authorization_request_id uuid, p_adapter_key text, p_expected_correlation_id uuid, p_expected_action text, p_expected_resource_type text, p_expected_resource_ref text default null, p_external_ref text default null, p_receipt jsonb default '{}'::jsonb) returns uuid language plpgsql security definer set search_path=sourceenergy_one,pg_temp as $$ declare ar sourceenergy_one.authorization_requests%rowtype; ad sourceenergy_one.domain_adapter_registry%rowtype; er_id uuid; begin select * into ar from sourceenergy_one.authorization_requests where id=p_authorization_request_id for update; if not found then raise exception 'authorization request not found'; end if; if ar.status<>'approved' then raise exception 'authorization request not approved'; end if; if ar.expires_at is not null and ar.expires_at<=now() then raise exception 'authorization request expired'; end if; if ar.consumed_at is not null then raise exception 'authorization request already consumed'; end if; if ar.correlation_id is distinct from p_expected_correlation_id or ar.action is distinct from p_expected_action or ar.resource_type is distinct from p_expected_resource_type or ar.resource_ref is distinct from p_expected_resource_ref then raise exception 'execution intent does not match authorization request'; end if; select * into ad from sourceenergy_one.domain_adapter_registry where adapter_key=p_adapter_key for update; if not found then raise exception 'adapter not found'; end if; if not ad.enabled then raise exception 'adapter disabled'; end if; if ad.mode<>'execute' then raise exception 'adapter not executable'; end if; begin insert into sourceenergy_one.execution_receipts(correlation_id,adapter_key,external_ref,status,receipt) values(ar.correlation_id,p_adapter_key,p_external_ref,'executed',coalesce(p_receipt,'{}'::jsonb)||jsonb_build_object('authorization_request_id',ar.id,'action',ar.action,'resource_type',ar.resource_type,'resource_ref',ar.resource_ref)) returning id into er_id; exception when unique_violation then raise exception 'authorized action already executed for adapter'; end; update sourceenergy_one.authorization_requests set consumed_at=now() where id=ar.id; insert into sourceenergy_one.audit_events(correlation_id,subject_id,actor_id,event_type,object_type,object_ref,payload) values(ar.correlation_id,ar.subject_id,coalesce(ar.decided_by,ar.requested_by),'authorized_action_executed','execution_receipt',er_id::text,jsonb_build_object('authorization_request_id',ar.id,'adapter_key',p_adapter_key,'action',ar.action)); return er_id; end; $$; revoke all on function sourceenergy_one.execute_authorized_action(uuid,text,uuid,text,text,text,text,jsonb) from public,anon,authenticated; grant execute on function sourceenergy_one.execute_authorized_action(uuid,text,uuid,text,text,text,text,jsonb) to service_role; comment on function sourceenergy_one.execute_authorized_action(uuid,text,uuid,text,text,text,text,jsonb) is 'Hardened final execution gate: approved, unexpired, unconsumed authorization; exact intent binding; enabled execute-mode adapter; concurrency-safe replay prevention; audit receipt.';
